-- 0018_writing_phrases: the writing phrase bank (Study → "Writing phrases",
-- and the phrase panel of the Writing page). Concept cards: the front is what
-- the learner wants to say (Vietnamese), the back the English frame to write it.
-- payload: back, note_vi, example, example_vi, group (shown with the card), order.
-- Written for this project; 81 frames.

INSERT INTO decks (subject_id, slug, name, description, default_kind, sort_order)
SELECT s.id, 'writing-phrases', 'Writing phrases',
       'Sentence frames for essays and emails: what you want to say -> how to write it', 'concept', 3
FROM subjects s WHERE s.slug = 'english'
ON CONFLICT (subject_id, slug) DO NOTHING;

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'concept', f.front, f.payload::jsonb, 'seed'
FROM (VALUES
  ('Ngày nay, … đang ngày càng phổ biến.', '{"back": "Nowadays, … is becoming increasingly common.", "note_vi": "Câu mở bài nêu bối cảnh. Chủ ngữ là danh từ hoặc V-ing.", "example": "Nowadays, working from home is becoming increasingly common.", "example_vi": "Ngày nay, làm việc tại nhà đang ngày càng phổ biến.", "group": "Mở bài", "order": 1}'),
  ('Trong những năm gần đây, …', '{"back": "In recent years, … has/have + V3", "note_vi": "Đi với thì hiện tại hoàn thành.", "example": "In recent years, online shopping has grown rapidly.", "example_vi": "Trong những năm gần đây, mua sắm trực tuyến đã tăng nhanh.", "group": "Mở bài", "order": 2}'),
  ('Có nhiều tranh luận về việc liệu …', '{"back": "There is much debate about whether …", "note_vi": "Dùng khi đề bài nêu hai quan điểm trái ngược.", "example": "There is much debate about whether cities should ban private cars.", "example_vi": "Có nhiều tranh luận về việc liệu các thành phố có nên cấm xe cá nhân.", "group": "Mở bài", "order": 3}'),
  ('Một số người cho rằng …, trong khi những người khác tin rằng …', '{"back": "Some people argue that …, while others believe that …", "note_vi": "Tóm tắt hai quan điểm của đề bài bằng lời của mình.", "example": "Some people argue that tourism helps local communities, while others believe that it harms them.", "example_vi": "Một số người cho rằng du lịch giúp ích cho cộng đồng địa phương, trong khi những người khác tin rằng nó gây hại.", "group": "Mở bài", "order": 4}'),
  ('… đã trở thành một mối lo ngại lớn.', '{"back": "… has become a major concern.", "note_vi": "Giới thiệu một vấn đề (ô nhiễm, giao thông…).", "example": "Plastic pollution has become a major concern in coastal towns.", "example_vi": "Ô nhiễm nhựa đã trở thành mối lo ngại lớn ở các thị trấn ven biển.", "group": "Mở bài", "order": 5}'),
  ('Bài viết này sẽ bàn về …', '{"back": "This essay will discuss …", "note_vi": "Câu cuối của mở bài: nói bài viết sẽ làm gì.", "example": "This essay will discuss both views before giving my own opinion.", "example_vi": "Bài viết này sẽ bàn về cả hai quan điểm trước khi đưa ra ý kiến của tôi.", "group": "Mở bài", "order": 6}'),
  ('Theo tôi, …', '{"back": "In my view, …", "note_vi": "Trung lập, dùng được trong mọi bài. Tránh lặp lại “I think” nhiều lần.", "example": "In my view, public transport should be free for students.", "example_vi": "Theo tôi, giao thông công cộng nên miễn phí cho học sinh, sinh viên.", "group": "Quan điểm", "order": 7}'),
  ('Tôi tin chắc rằng …', '{"back": "I firmly believe that …", "note_vi": "Quan điểm mạnh, hay dùng trong mở bài hoặc kết luận.", "example": "I firmly believe that every child should learn to swim.", "example_vi": "Tôi tin chắc rằng mọi trẻ em nên học bơi.", "group": "Quan điểm", "order": 8}'),
  ('Tôi hoàn toàn đồng ý rằng …', '{"back": "I completely agree that …", "note_vi": "Đồng ý hoàn toàn với đề bài.", "example": "I completely agree that companies should reduce plastic packaging.", "example_vi": "Tôi hoàn toàn đồng ý rằng các công ty nên giảm bao bì nhựa.", "group": "Quan điểm", "order": 9}'),
  ('Tôi không đồng ý với quan điểm rằng …', '{"back": "I disagree with the view that …", "note_vi": "Không đồng ý một cách lịch sự. Sau “the view” là “that + mệnh đề”.", "example": "I disagree with the view that university should be free for everyone.", "example_vi": "Tôi không đồng ý với quan điểm rằng đại học nên miễn phí cho tất cả mọi người.", "group": "Quan điểm", "order": 10}'),
  ('Tôi đồng ý ở một mức độ nào đó rằng …', '{"back": "I agree to some extent that …", "note_vi": "Đồng ý một phần: sau đó nêu cả mặt đúng và mặt chưa đúng.", "example": "I agree to some extent that technology makes people less social.", "example_vi": "Tôi đồng ý ở một mức độ nào đó rằng công nghệ khiến con người ít giao tiếp hơn.", "group": "Quan điểm", "order": 11}'),
  ('Không có gì phải nghi ngờ rằng …', '{"back": "There is no doubt that …", "note_vi": "Khẳng định một điều hiển nhiên, dùng vừa phải.", "example": "There is no doubt that the internet has changed the way we work.", "example_vi": "Không có gì phải nghi ngờ rằng internet đã thay đổi cách chúng ta làm việc.", "group": "Quan điểm", "order": 12}'),
  ('Lý do chính là …', '{"back": "The main reason is that …", "note_vi": "Sau “that” là một mệnh đề đầy đủ (chủ ngữ + động từ).", "example": "The main reason is that housing in the city is too expensive.", "example_vi": "Lý do chính là nhà ở trong thành phố quá đắt.", "group": "Lý do", "order": 13}'),
  ('Điều này là bởi vì …', '{"back": "This is because …", "note_vi": "Giải thích cho câu ngay trước đó.", "example": "This is because young people spend more time online.", "example_vi": "Điều này là bởi vì người trẻ dành nhiều thời gian trên mạng hơn.", "group": "Lý do", "order": 14}'),
  ('do / vì (+ danh từ)', '{"back": "due to + noun / V-ing", "note_vi": "Sau “due to” là danh từ, không phải mệnh đề. Với mệnh đề dùng “because”.", "example": "Many flights were cancelled due to the storm.", "example_vi": "Nhiều chuyến bay bị huỷ do cơn bão.", "group": "Lý do", "order": 15}'),
  ('Một lý do khác là …', '{"back": "Another reason is that …", "note_vi": "Mở đầu đoạn hoặc ý thứ hai.", "example": "Another reason is that cycling is cheaper than driving.", "example_vi": "Một lý do khác là đi xe đạp rẻ hơn lái ô tô.", "group": "Lý do", "order": 16}'),
  ('Lý do đầu tiên khiến … là …', '{"back": "The first reason why … is that …", "note_vi": "Mở đầu đoạn thân bài thứ nhất.", "example": "The first reason why people move to cities is that there are more jobs.", "example_vi": "Lý do đầu tiên khiến người ta chuyển đến thành phố là có nhiều việc làm hơn.", "group": "Lý do", "order": 17}'),
  ('Ví dụ, …', '{"back": "For example, …", "note_vi": "Đứng đầu câu, có dấu phẩy. Cũng dùng “For instance, …”.", "example": "For example, many offices now let staff work from home two days a week.", "example_vi": "Ví dụ, nhiều văn phòng hiện cho nhân viên làm việc tại nhà hai ngày mỗi tuần.", "group": "Ví dụ", "order": 18}'),
  ('chẳng hạn như (+ danh từ)', '{"back": "such as + noun", "note_vi": "Đứng giữa câu, trước danh sách danh từ. Không đặt đầu câu.", "example": "Renewable energy sources, such as solar and wind power, are becoming cheaper.", "example_vi": "Các nguồn năng lượng tái tạo, chẳng hạn như điện mặt trời và điện gió, đang rẻ dần.", "group": "Ví dụ", "order": 19}'),
  ('Một ví dụ điển hình cho điều này là …', '{"back": "A good example of this is …", "note_vi": "Sau đó là danh từ hoặc tên riêng.", "example": "A good example of this is Singapore, which has very clean streets.", "example_vi": "Một ví dụ điển hình cho điều này là Singapore, nơi đường phố rất sạch.", "group": "Ví dụ", "order": 20}'),
  ('Điều này có thể thấy rõ ở …', '{"back": "This can be seen in …", "note_vi": "Dẫn chứng bằng một hiện tượng thực tế.", "example": "This can be seen in the rise of online learning during the pandemic.", "example_vi": "Điều này có thể thấy rõ ở sự phát triển của học trực tuyến trong đại dịch.", "group": "Ví dụ", "order": 21}'),
  ('Theo một nghiên cứu gần đây, …', '{"back": "According to a recent study, …", "note_vi": "Dẫn chứng có số liệu; không cần ghi tên nghiên cứu.", "example": "According to a recent study, most teenagers sleep less than eight hours a night.", "example_vi": "Theo một nghiên cứu gần đây, phần lớn thanh thiếu niên ngủ ít hơn tám tiếng mỗi đêm.", "group": "Ví dụ", "order": 22}'),
  ('Ngoài ra, …', '{"back": "In addition, …", "note_vi": "Thêm một ý cùng hướng. Đứng đầu câu, có dấu phẩy.", "example": "In addition, public parks give children a safe place to play.", "example_vi": "Ngoài ra, công viên công cộng cho trẻ em một nơi an toàn để vui chơi.", "group": "Thêm ý", "order": 23}'),
  ('Hơn nữa, …', '{"back": "Furthermore, …", "note_vi": "Trang trọng hơn “Also”. Đứng đầu câu, có dấu phẩy.", "example": "Furthermore, electric buses are much quieter than diesel ones.", "example_vi": "Hơn nữa, xe buýt điện yên tĩnh hơn nhiều so với xe chạy dầu.", "group": "Thêm ý", "order": 24}'),
  ('không chỉ … mà còn …', '{"back": "not only … but also …", "note_vi": "Hai vế cùng loại từ (tính từ – tính từ, động từ – động từ).", "example": "Cycling is not only cheap but also good for your health.", "example_vi": "Đi xe đạp không chỉ rẻ mà còn tốt cho sức khỏe.", "group": "Thêm ý", "order": 25}'),
  ('Bên cạnh việc …, …', '{"back": "Besides + V-ing / noun, …", "note_vi": "Sau “Besides” là V-ing hoặc danh từ.", "example": "Besides saving money, cooking at home is often healthier.", "example_vi": "Bên cạnh việc tiết kiệm tiền, nấu ăn ở nhà thường lành mạnh hơn.", "group": "Thêm ý", "order": 26}'),
  ('Một điểm quan trọng khác là …', '{"back": "Another important point is that …", "note_vi": "Chuyển sang ý mới trong cùng đoạn.", "example": "Another important point is that older people need help with technology.", "example_vi": "Một điểm quan trọng khác là người lớn tuổi cần được giúp đỡ về công nghệ.", "group": "Thêm ý", "order": 27}'),
  ('Tuy nhiên, …', '{"back": "However, …", "note_vi": "Đứng đầu câu mới, có dấu phẩy. Không nối hai mệnh đề bằng dấu phẩy + however.", "example": "However, the cost of living in big cities is very high.", "example_vi": "Tuy nhiên, chi phí sinh hoạt ở các thành phố lớn rất cao.", "group": "Đối lập", "order": 28}'),
  ('Mặc dù … (+ mệnh đề), …', '{"back": "Although + clause, …", "note_vi": "Không dùng “but” trong cùng câu với “although”.", "example": "Although the plan is expensive, it will save money in the long run.", "example_vi": "Mặc dù kế hoạch tốn kém, nó sẽ tiết kiệm tiền về lâu dài.", "group": "Đối lập", "order": 29}'),
  ('Mặc dù (+ danh từ / V-ing), …', '{"back": "Despite + noun / V-ing, …", "note_vi": "Sau “Despite” là danh từ hoặc V-ing, không phải mệnh đề.", "example": "Despite the high cost, many families choose private schools.", "example_vi": "Mặc dù chi phí cao, nhiều gia đình vẫn chọn trường tư.", "group": "Đối lập", "order": 30}'),
  ('Mặt khác, …', '{"back": "On the other hand, …", "note_vi": "Nêu mặt đối lập của vấn đề.", "example": "On the other hand, working from home can make people feel lonely.", "example_vi": "Mặt khác, làm việc tại nhà có thể khiến người ta cảm thấy cô đơn.", "group": "Đối lập", "order": 31}'),
  ('Trong khi …, thì …', '{"back": "While …, …", "note_vi": "Đặt hai ý tương phản trong một câu.", "example": "While some jobs will disappear, new ones will be created.", "example_vi": "Trong khi một số công việc sẽ mất đi, thì những công việc mới sẽ được tạo ra.", "group": "Đối lập", "order": 32}'),
  ('Dù vậy, …', '{"back": "Nevertheless, …", "note_vi": "Trang trọng; dùng sau khi đã thừa nhận một điểm trái ngược.", "example": "Nevertheless, the benefits of the project are clear.", "example_vi": "Dù vậy, lợi ích của dự án là rõ ràng.", "group": "Đối lập", "order": 33}'),
  ('Điều này dẫn đến …', '{"back": "This leads to + noun", "note_vi": "Sau “lead to” là danh từ hoặc V-ing.", "example": "This leads to serious traffic congestion in the city centre.", "example_vi": "Điều này dẫn đến tắc nghẽn giao thông nghiêm trọng ở trung tâm thành phố.", "group": "Nguyên nhân – kết quả", "order": 34}'),
  ('Kết quả là, …', '{"back": "As a result, …", "note_vi": "Đứng đầu câu, nối với hệ quả của câu trước.", "example": "As a result, many young people cannot afford to buy a house.", "example_vi": "Kết quả là, nhiều người trẻ không đủ khả năng mua nhà.", "group": "Nguyên nhân – kết quả", "order": 35}'),
  ('… khiến cho … (+ động từ)', '{"back": "… causes + sb/sth + to + V", "note_vi": "Không dùng “cause … getting bad”; đúng là “cause something to worsen”.", "example": "Discarded plastic has caused water quality to worsen.", "example_vi": "Rác nhựa bị vứt bỏ đã khiến chất lượng nước xấu đi.", "group": "Nguyên nhân – kết quả", "order": 36}'),
  ('Do đó, …', '{"back": "Therefore, …", "note_vi": "Kết luận logic từ ý trước. Đầu câu hoặc sau dấu chấm phẩy.", "example": "Therefore, the city needs more public transport.", "example_vi": "Do đó, thành phố cần thêm phương tiện công cộng.", "group": "Nguyên nhân – kết quả", "order": 37}'),
  ('… có ảnh hưởng tiêu cực đến …', '{"back": "… has a negative impact on …", "note_vi": "Đi với giới từ “on”. Tích cực: “a positive impact on”.", "example": "Noise from the airport has a negative impact on local residents.", "example_vi": "Tiếng ồn từ sân bay có ảnh hưởng tiêu cực đến cư dân địa phương.", "group": "Nguyên nhân – kết quả", "order": 38}'),
  ('Nguyên nhân chính của … là …', '{"back": "The main cause of … is …", "note_vi": "“cause of” + danh từ (vấn đề), sau “is” là danh từ hoặc V-ing.", "example": "The main cause of air pollution is traffic.", "example_vi": "Nguyên nhân chính của ô nhiễm không khí là giao thông.", "group": "Nguyên nhân – kết quả", "order": 39}'),
  ('… đã làm cho … tồi tệ hơn', '{"back": "… has made … worse", "note_vi": "make + tân ngữ + tính từ (worse, better, easier).", "example": "Rapid development has made the flooding problem worse.", "example_vi": "Sự phát triển nhanh đã làm cho vấn đề ngập lụt tồi tệ hơn.", "group": "Nguyên nhân – kết quả", "order": 40}'),
  ('Một giải pháp khả thi là …', '{"back": "One possible solution is to + V", "note_vi": "Sau “is to” là động từ nguyên mẫu.", "example": "One possible solution is to improve public transport.", "example_vi": "Một giải pháp khả thi là cải thiện giao thông công cộng.", "group": "Giải pháp", "order": 41}'),
  ('Chính phủ nên …', '{"back": "The government should + V", "note_vi": "Đề xuất trực tiếp; thay chủ ngữ bằng “Schools / Companies / Parents”.", "example": "The government should invest more in public hospitals.", "example_vi": "Chính phủ nên đầu tư nhiều hơn vào bệnh viện công.", "group": "Giải pháp", "order": 42}'),
  ('Cần có biện pháp để …', '{"back": "Measures should be taken to + V", "note_vi": "Bị động, trang trọng: không cần nói ai làm.", "example": "Measures should be taken to reduce plastic waste.", "example_vi": "Cần có biện pháp để giảm rác thải nhựa.", "group": "Giải pháp", "order": 43}'),
  ('Vấn đề này có thể được giải quyết bằng cách …', '{"back": "This problem can be solved by + V-ing", "note_vi": "Sau “by” là V-ing.", "example": "This problem can be solved by planting more trees.", "example_vi": "Vấn đề này có thể được giải quyết bằng cách trồng thêm cây.", "group": "Giải pháp", "order": 44}'),
  ('Điều quan trọng là … phải …', '{"back": "It is important for sb to + V", "note_vi": "Nhấn mạnh việc cần làm của một nhóm người.", "example": "It is important for parents to limit their children''s screen time.", "example_vi": "Điều quan trọng là cha mẹ phải giới hạn thời gian dùng màn hình của con.", "group": "Giải pháp", "order": 45}'),
  ('Nâng cao nhận thức về …', '{"back": "raise awareness of …", "note_vi": "Không dùng “civil cognizant”; “awareness” là danh từ, đi với “of”.", "example": "Schools could raise awareness of recycling among young people.", "example_vi": "Trường học có thể nâng cao nhận thức về tái chế trong giới trẻ.", "group": "Giải pháp", "order": 46}'),
  ('Lợi ích chính của … là …', '{"back": "The main advantage of … is that …", "note_vi": "Mở đầu đoạn nói về ưu điểm.", "example": "The main advantage of online courses is that students can study at their own pace.", "example_vi": "Lợi ích chính của khóa học trực tuyến là người học có thể học theo tốc độ của mình.", "group": "Ưu – nhược điểm", "order": 47}'),
  ('Mặt trái của … là …', '{"back": "The downside of … is that …", "note_vi": "Mở đầu ý về nhược điểm; trang trọng hơn: “The main drawback of …”.", "example": "The downside of living in the city centre is that it is noisy.", "example_vi": "Mặt trái của việc sống ở trung tâm thành phố là ồn ào.", "group": "Ưu – nhược điểm", "order": 48}'),
  ('Lợi ích lớn hơn bất lợi.', '{"back": "The benefits outweigh the drawbacks.", "note_vi": "Kết luận cho dạng bài “advantages outweigh disadvantages?”.", "example": "In my view, the benefits of tourism outweigh the drawbacks.", "example_vi": "Theo tôi, lợi ích của du lịch lớn hơn bất lợi.", "group": "Ưu – nhược điểm", "order": 49}'),
  ('… có cả ưu điểm và nhược điểm.', '{"back": "… has both advantages and disadvantages.", "note_vi": "Câu mở bài cho dạng bài ưu – nhược điểm.", "example": "Working from home has both advantages and disadvantages.", "example_vi": "Làm việc tại nhà có cả ưu điểm và nhược điểm.", "group": "Ưu – nhược điểm", "order": 50}'),
  ('… mang lại nhiều lợi ích cho …', '{"back": "… brings many benefits to …", "note_vi": "Đi với giới từ “to”.", "example": "The new park brings many benefits to the local community.", "example_vi": "Công viên mới mang lại nhiều lợi ích cho cộng đồng địa phương.", "group": "Ưu – nhược điểm", "order": 51}'),
  ('Tóm lại, …', '{"back": "In conclusion, …", "note_vi": "Mở đầu đoạn kết; nhắc lại quan điểm bằng từ khác.", "example": "In conclusion, I believe that cities should invest in cycling lanes.", "example_vi": "Tóm lại, tôi tin rằng các thành phố nên đầu tư vào làn đường cho xe đạp.", "group": "Kết luận", "order": 52}'),
  ('Nhìn chung, …', '{"back": "Overall, …", "note_vi": "Tóm ý chung; cũng dùng cho mô tả biểu đồ (IELTS Task 1).", "example": "Overall, the advantages of the plan are greater than its costs.", "example_vi": "Nhìn chung, ưu điểm của kế hoạch lớn hơn chi phí của nó.", "group": "Kết luận", "order": 53}'),
  ('Xét mọi khía cạnh, …', '{"back": "All things considered, …", "note_vi": "Kết luận sau khi đã cân nhắc hai mặt.", "example": "All things considered, studying abroad is a valuable experience.", "example_vi": "Xét mọi khía cạnh, du học là một trải nghiệm quý giá.", "group": "Kết luận", "order": 54}'),
  ('Vì những lý do trên, tôi cho rằng …', '{"back": "For these reasons, I believe that …", "note_vi": "Nối phần lý do với quan điểm cuối cùng.", "example": "For these reasons, I believe that homework should be limited.", "example_vi": "Vì những lý do trên, tôi cho rằng bài tập về nhà nên được giới hạn.", "group": "Kết luận", "order": 55}'),
  ('Trong tương lai, … có khả năng sẽ …', '{"back": "In the future, … is likely to + V", "note_vi": "Dự đoán; “be likely to + V”.", "example": "In the future, remote work is likely to become the norm.", "example_vi": "Trong tương lai, làm việc từ xa có khả năng sẽ trở thành điều bình thường.", "group": "Kết luận", "order": 56}'),
  ('Kính gửi ông/bà … (biết tên)', '{"back": "Dear Mr/Ms + surname,", "note_vi": "Biết tên người nhận: Dear Mr/Ms + họ, kết thư bằng “Yours sincerely”. Không biết tên: “Dear Sir or Madam,”.", "example": "Dear Mr Davis,", "example_vi": "Kính gửi ông Davis,", "group": "Email: mở đầu", "order": 57}'),
  ('Tôi viết thư này để …', '{"back": "I am writing to + V", "note_vi": "Câu đầu tiên của thư: nêu mục đích (inquire about / report on / apply for …).", "example": "I am writing to report on the condition of Oldport Harbour.", "example_vi": "Tôi viết thư này để báo cáo về tình trạng của cảng Oldport.", "group": "Email: mở đầu", "order": 58}'),
  ('Tôi viết thư này để phản hồi …', '{"back": "I am writing in response to + noun", "note_vi": "Trả lời một thư, quảng cáo hoặc thông báo trước đó.", "example": "I am writing in response to your email of 12 May.", "example_vi": "Tôi viết thư này để phản hồi email ngày 12 tháng 5 của ông/bà.", "group": "Email: mở đầu", "order": 59}'),
  ('Cảm ơn anh/chị đã …', '{"back": "Thank you for + V-ing / noun", "note_vi": "Sau “for” là V-ing hoặc danh từ.", "example": "Thank you for sending the report so quickly.", "example_vi": "Cảm ơn anh/chị đã gửi báo cáo nhanh như vậy.", "group": "Email: mở đầu", "order": 60}'),
  ('Tôi xin cập nhật cho anh/chị về …', '{"back": "I would like to update you on …", "note_vi": "Thay cho “say about the status”; đi với giới từ “on”.", "example": "I would like to update you on the progress of the project.", "example_vi": "Tôi xin cập nhật cho anh/chị về tiến độ dự án.", "group": "Email: mở đầu", "order": 61}'),
  ('Sau buổi họp của chúng ta vào …,', '{"back": "Following our meeting on …,", "note_vi": "Nhắc lại cuộc trao đổi trước; “on” + ngày.", "example": "Following our meeting on Monday, I have prepared a new budget.", "example_vi": "Sau buổi họp của chúng ta vào thứ Hai, tôi đã chuẩn bị ngân sách mới.", "group": "Email: mở đầu", "order": 62}'),
  ('Anh/chị vui lòng … được không?', '{"back": "Could you please + V …?", "note_vi": "Yêu cầu lịch sự, phổ biến nhất.", "example": "Could you please send me the updated price list?", "example_vi": "Anh/chị vui lòng gửi tôi bảng giá mới được không?", "group": "Email: đề nghị", "order": 63}'),
  ('Tôi sẽ rất biết ơn nếu anh/chị có thể …', '{"back": "I would be grateful if you could + V", "note_vi": "Trang trọng hơn “Could you please”. Dùng “if”, không dùng “that”.", "example": "I would be grateful if you could confirm the date of the meeting.", "example_vi": "Tôi sẽ rất biết ơn nếu anh/chị có thể xác nhận ngày họp.", "group": "Email: đề nghị", "order": 64}'),
  ('Tôi muốn hỏi về …', '{"back": "I would like to inquire about + noun", "note_vi": "Hỏi thông tin (khóa học, dịch vụ, giá…). Anh-Anh: “enquire”.", "example": "I would like to inquire about the evening English course.", "example_vi": "Tôi muốn hỏi về khóa tiếng Anh buổi tối.", "group": "Email: đề nghị", "order": 65}'),
  ('Vui lòng cho tôi biết …', '{"back": "Please let me know + if / wh-", "note_vi": "Thường dùng ở cuối thư.", "example": "Please let me know if you need any further information.", "example_vi": "Vui lòng cho tôi biết nếu anh/chị cần thêm thông tin.", "group": "Email: đề nghị", "order": 66}'),
  ('Tôi xin đề xuất rằng chúng ta nên …', '{"back": "I would like to suggest that we + V", "note_vi": "Sau “suggest that we” là động từ nguyên mẫu.", "example": "I would like to suggest that we move the meeting to Friday.", "example_vi": "Tôi xin đề xuất rằng chúng ta nên dời cuộc họp sang thứ Sáu.", "group": "Email: đề nghị", "order": 67}'),
  ('Tôi xin gửi kèm …', '{"back": "Please find attached + noun", "note_vi": "Báo có tệp đính kèm.", "example": "Please find attached the revised schedule.", "example_vi": "Tôi xin gửi kèm lịch trình đã chỉnh sửa.", "group": "Email: đề nghị", "order": 68}'),
  ('Tôi viết thư này để phàn nàn về …', '{"back": "I am writing to complain about + noun / V-ing", "note_vi": "Phàn nàn lịch sự; sau “about” là danh từ hoặc V-ing.", "example": "I am writing to complain about the noise from the building site.", "example_vi": "Tôi viết thư này để phàn nàn về tiếng ồn từ công trường.", "group": "Email: báo vấn đề", "order": 69}'),
  ('Tôi viết thư để thông báo rằng …', '{"back": "I am writing to inform you that …", "note_vi": "Báo một tin chính thức.", "example": "I am writing to inform you that the office will be closed on Friday.", "example_vi": "Tôi viết thư để thông báo rằng văn phòng sẽ đóng cửa vào thứ Sáu.", "group": "Email: báo vấn đề", "order": 70}'),
  ('Đáng tiếc là, …', '{"back": "Unfortunately, …", "note_vi": "Mở đầu câu báo tin xấu.", "example": "Unfortunately, the parts we ordered have not arrived.", "example_vi": "Đáng tiếc là, các linh kiện chúng tôi đặt vẫn chưa đến.", "group": "Email: báo vấn đề", "order": 71}'),
  ('Vấn đề là …', '{"back": "The problem is that …", "note_vi": "Nêu rõ vấn đề bằng một mệnh đề đầy đủ.", "example": "The problem is that the heating has not worked for a week.", "example_vi": "Vấn đề là hệ thống sưởi đã không hoạt động một tuần nay.", "group": "Email: báo vấn đề", "order": 72}'),
  ('… đang xấu đi', '{"back": "… is deteriorating", "note_vi": "Thì hiện tại tiếp diễn; không dùng “getting to deteriorate”.", "example": "The water quality in the harbour is deteriorating.", "example_vi": "Chất lượng nước ở cảng đang xấu đi.", "group": "Email: báo vấn đề", "order": 73}'),
  ('Tôi hy vọng việc này sẽ sớm được giải quyết.', '{"back": "I hope this matter can be resolved as soon as possible.", "note_vi": "Câu cuối của thư phàn nàn.", "example": "I hope this matter can be resolved as soon as possible.", "example_vi": "Tôi hy vọng việc này sẽ sớm được giải quyết.", "group": "Email: báo vấn đề", "order": 74}'),
  ('Xin lỗi vì sự bất tiện này.', '{"back": "I apologise for any inconvenience caused.", "note_vi": "Xin lỗi trong thư công việc. Anh-Mỹ: “apologize”.", "example": "I apologise for any inconvenience caused by the delay.", "example_vi": "Tôi xin lỗi vì sự bất tiện do việc chậm trễ gây ra.", "group": "Email: báo vấn đề", "order": 75}'),
  ('Tôi mong sớm nhận được hồi âm.', '{"back": "I look forward to hearing from you.", "note_vi": "“look forward to” + V-ing (không phải động từ nguyên mẫu).", "example": "I look forward to hearing from you.", "example_vi": "Tôi mong sớm nhận được hồi âm của anh/chị.", "group": "Email: kết thư", "order": 76}'),
  ('Nếu có câu hỏi gì, xin đừng ngần ngại liên hệ.', '{"back": "If you have any questions, please do not hesitate to contact me.", "note_vi": "Câu kết lịch sự trước lời chào.", "example": "If you have any questions, please do not hesitate to contact me.", "example_vi": "Nếu có câu hỏi gì, xin đừng ngần ngại liên hệ với tôi.", "group": "Email: kết thư", "order": 77}'),
  ('Cảm ơn anh/chị đã dành thời gian xem xét.', '{"back": "Thank you for your time and consideration.", "note_vi": "Kết thư xin việc hoặc đề nghị.", "example": "Thank you for your time and consideration.", "example_vi": "Cảm ơn anh/chị đã dành thời gian xem xét.", "group": "Email: kết thư", "order": 78}'),
  ('Trân trọng, (đã biết tên người nhận)', '{"back": "Yours sincerely,", "note_vi": "Dùng khi mở đầu bằng “Dear Mr/Ms + họ”. Thân mật hơn: “Best regards,”.", "example": "Yours sincerely,\nAnna Tran", "example_vi": "Trân trọng,\nAnna Tran", "group": "Email: kết thư", "order": 79}'),
  ('Trân trọng, (không biết tên người nhận)', '{"back": "Yours faithfully,", "note_vi": "Dùng khi mở đầu bằng “Dear Sir or Madam,” (Anh-Anh).", "example": "Yours faithfully,\nAnna Tran", "example_vi": "Trân trọng,\nAnna Tran", "group": "Email: kết thư", "order": 80}'),
  ('Tôi rất mong được làm việc cùng anh/chị.', '{"back": "I look forward to working with you.", "note_vi": "Kết thư cho đối tác hoặc đồng nghiệp mới.", "example": "I look forward to working with you on this project.", "example_vi": "Tôi rất mong được làm việc cùng anh/chị trong dự án này.", "group": "Email: kết thư", "order": 81}')
) AS f(front, payload)
JOIN decks d ON d.slug = 'writing-phrases'
JOIN subjects s ON s.id = d.subject_id AND s.slug = 'english'
ON CONFLICT DO NOTHING;
